def predict(board, action):
    row, col = action
    mouse_row, mouse_col = row, col
    new_board = [list(row) for row in board]

    for i in range(max(0, mouse_row-1), min(63, mouse_row+2)):
        for j in range(max(0, mouse_col-1), min(63, mouse_col+2)):
            if (i, j) != (mouse_row, mouse_col):
                if new_board[i][j] == 'B':
                    new_board[i][j] = 'S'
                elif new_board[i][j] == 'G':
                    new_board[i][j] = 'N'

    new_board[mouse_row][mouse_col] = 'p'
    return [''.join(row) for row in new_board]
